+// crossRepoExplainSessionIndex maps the --session-index flag to the reader's
+// convention (-1 = latest), so an unset flag reads the latest session.
+func crossRepoExplainSessionIndex(changed bool, value int) int {
+	if !changed {
+		return -1
+	}
+	return value
+}
